-- PT115-S4-Q26. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT115-S4-Q26$batch12$ AND q.stimulus=$batch12$Commentator: Because of teacher hiring freezes, the quality of education in that country will not improve. Thus, it will surely deteriorate.$batch12$ AND q.prompt=$batch12$The flawed reasoning in which one of the following is most similar to that in the commentator's argument?$batch12$ AND q.correct_choice=$batch12$D$batch12$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q26'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT115-S4-Q26$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q26'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT115-S4-Q26$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Education quality will surely deteriorate.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Because of hiring freezes, quality won't improve.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Not improving leaves two options: staying the same or getting worse. The argument ignores staying the same.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Won't go up, so must go down.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT115-S4-Q26$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This picks one lunch from many, but it isn't about a direction of change with a middle option.$batch12$), ($batch12$B$batch12$, $batch12$This is a probability judgment about proof and disproof.$batch12$), ($batch12$C$batch12$, $batch12$"It may become more discordant" is a hedged conclusion, and a fair one. The original says "surely," and that certainty is the flaw.$batch12$), ($batch12$D$batch12$, $batch12$The temperature can't rise, so it must fall. That ignores staying the same, just like the original.$batch12$), ($batch12$E$batch12$, $batch12$A dead starter does mean the car won't start. Valid.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT115-S4-Q26$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
